[
  {
    "type": "function",
    "name": "list_issues",
    "description": "Listet bekannte GitHub-Issues aus dem Snapshot (state=open|closed|all). read-only, schreibt nichts.",
    "parameters": {
      "type": "object",
      "properties": {
        "state": {
          "type": "string",
          "default": "all"
        },
        "limit": {
          "type": "integer",
          "default": 100
        }
      }
    }
  },
  {
    "type": "function",
    "name": "get_issue",
    "description": "Liest ein einzelnes GitHub-Issue (Titel, Body, State, Labels) per Nummer aus dem Snapshot.",
    "parameters": {
      "type": "object",
      "properties": {
        "issueNumber": {
          "type": "integer"
        }
      },
      "required": [
        "issueNumber"
      ]
    }
  },
  {
    "type": "function",
    "name": "search_issues",
    "description": "Sucht Issues per Stichwort-Overlap (Titel/Body/Labels). Vor einem CREATE nutzen, um Duplikate zu finden.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "state": {
          "type": "string",
          "default": "all"
        },
        "limit": {
          "type": "integer",
          "default": 20
